t.script:
window.dataLayer = window.dataLayer || [];
function gtag(){dataLayer.push(arguments);}
gtag('js', new Date());
gtag('config', '');

{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "Do you deliver pet supplies across Dar es Salaam?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes! Stephan's Pet Store delivers across all Dar es Salaam neighborhoods including Masaki, Mikocheni, Oysterbay, Kinondoni, Upanga, City Centre, and Mbezi. Free delivery is provided on orders over TSh 100,000."
      }
    },
    {
      "@type": "Question",
      "name": "Do you deliver pet products upcountry outside Dar es Salaam?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes, we dispatch pet food, accessories and hygiene products across Tanzania (Arusha, Dodoma, Mwanza, Morogoro, Mtwara, Zanzibar) via reliable regional parcel and bus courier services within 24 to 48 hours."
      }
    },
    {
      "@type": "Question",
      "name": "How can I book a pet grooming appointment?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "You can book directly through our online Grooming page (https://www.stephanspetstore.co.tz/grooming) by choosing your pet type, coat size, package and time slot, or contact our grooming studio on WhatsApp at +255 786 627 873."
      }
    },
    {
      "@type": "Question",
      "name": "Which payment methods are accepted at Stephan's Pet Store?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "We accept Selcom Mobile Money (Vodacom M-Pesa, Airtel Money, Mixx by Yas / Tigo Pesa, Halopesa), Visa and Mastercard, Sky Wallet rewards points, and Cash on Delivery / Store Pickup."
      }
    },
    {
      "@type": "Question",
      "name": "What is your return and exchange policy?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Unopened pet supplies in original manufacturer packaging with security seals intact can be returned or exchanged within 7 days of purchase. Perishable pet food and opened grooming supplies cannot be returned for biosecurity and hygiene reasons."
      }
    },
    {
      "@type": "Question",
      "name": "Where are Stephan's Pet Store physical locations in Dar es Salaam?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "We have two locations in Dar es Salaam: 1) Masaki Flagship Store & Grooming Studio at 11 Slipway Road (open Mon–Sat 9:00 AM – 8:30 PM); 2) Mikocheni Store at 59 Mikocheni A (open Mon–Sat 9:00 AM – 6:00 PM)."
      }
    }
  ]
}
